object Solution {
  def minSkips(dist: Array[Int], speed: Int, hoursBefore: Int): Int = {
    val n = dist.length
    val INF = 1e15

    // dp(i)(k): minimum time to finish first i roads with k skips
    // Use Double for time
    val dp = Array.fill(n + 1, n + 1)(INF)
    dp(0)(0) = 0.0

    for (i <- 1 to n) {
      val t = dist(i - 1).toDouble / speed
      for (k <- 0 to i) {
        if (k <= i - 1) {
          // Not skip rest after previous road (except last road)
          // For i-th road, if i < n, we must wait for next integer hour after finishing
          // For i == n, no waiting needed
          val prevTime = dp(i - 1)(k)
          if (prevTime < INF) {
            val timeAfterTravel = prevTime + t
            val waitTime = if (i == n) timeAfterTravel else math.ceil(timeAfterTravel)
            dp(i)(k) = math.min(dp(i)(k), waitTime)
          }
        }
        if (k > 0) {
          // Skip rest after previous road
          val prevTimeSkip = dp(i - 1)(k - 1)
          if (prevTimeSkip < INF) {
            val timeAfterTravelSkip = prevTimeSkip + t
            // No waiting, just add travel time
            dp(i)(k) = math.min(dp(i)(k), timeAfterTravelSkip)
          }
        }
      }
    }

    for (k <- 0 to n) {
      if (dp(n)(k) <= hoursBefore) return k
    }
    -1
  }
}

